using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    [ColumnName("Category")]
    public string Category { get; set; } = string.Empty;
}

using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string PredictedCategory { get; set; } = string.Empty;

    public float[]? Score { get; set; }
}

using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketModelService
{
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly EvaluationMetrics _metrics;

    public TicketModelService(IWebHostEnvironment env, ILogger<TicketModelService> logger)
    {
        var mlContext = new MLContext(seed: 0);

        var csvPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        var dataView = mlContext.Data.LoadFromTextFile<TicketData>(
            csvPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = mlContext.Transforms.Conversion
            .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // Cross-validate on the small dataset
        var cvResults = mlContext.MulticlassClassification.CrossValidate(dataView, pipeline, numberOfFolds: 3);

        var avgMacro = cvResults.Average(r => r.Metrics.MacroAccuracy);
        var avgMicro = cvResults.Average(r => r.Metrics.MicroAccuracy);
        var avgLogLoss = cvResults.Average(r => r.Metrics.LogLoss);

        logger.LogInformation("Cross-validation metrics — MacroAccuracy: {Macro:F4}, MicroAccuracy: {Micro:F4}, LogLoss: {LogLoss:F4}",
            avgMacro, avgMicro, avgLogLoss);

        _metrics = new EvaluationMetrics(avgMacro, avgMicro, avgLogLoss);

        // Train final model on full dataset
        var model = pipeline.Fit(dataView);
        _predictionEngine = mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(model);
    }

    public TicketPrediction Predict(TicketData input) => _predictionEngine.Predict(input);

    public EvaluationMetrics GetMetrics() => _metrics;
}

using Microsoft.AspNetCore.Mvc;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api")]
public class TicketClassifierController : ControllerBase
{
    private readonly TicketModelService _modelService;

    public TicketClassifierController(TicketModelService modelService)
    {
        _modelService = modelService;
    }

    [HttpPost("classify")]
    public IActionResult Classify([FromBody] ClassifyRequest request)
    {
        var input = new TicketData
        {
            Subject = request.Subject ?? string.Empty,
            Description = request.Description ?? string.Empty,
            Priority = request.Priority
        };

        var prediction = _modelService.Predict(input);

        return Ok(new
        {
            predictedCategory = prediction.PredictedCategory,
            confidenceScores = prediction.Score
        });
    }

    [HttpGet("metrics")]
    public IActionResult GetMetrics()
    {
        return Ok(_modelService.GetMetrics());
    }
}

public class ClassifyRequest
{
    public string? Subject { get; set; }
    public string? Description { get; set; }
    public float Priority { get; set; }
}

